/* CreativeHub Design System */
:root {
  /* Colors - bold, modern, professional */
  --primary: #F02D00;
  --primary-dark: #D12600;
  --secondary: #171717;
  --background: #FFFFFF;
  --surface: #F8FAFC;
  --surface-2: #F1F5F9;
  --text-primary: #171717;
  --text-secondary: #64748B;
  --text-muted: #94A3B8;
  --accent: #00C9A7;
  --accent-hover: #00B094;
  --success: #10B981;
  --warning: #F59E0B;
  --error: #EF4444;

  /* Typography */
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset & Base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--background);
  min-height: 100vh;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, textarea, select { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-primary);
}

h1 { font-size: 3rem; font-weight: 700; }
h2 { font-size: 2.25rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

p { color: var(--text-secondary); }

/* Utility Classes */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--secondary);
  color: white;
}

.btn-outline {
  border: 2px solid var(--secondary);
  background: transparent;
}

.btn-outline:hover {
  background: var(--secondary);
  color: white;
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
}

.btn-ghost:hover {
  background: var(--surface-2);
}

/* Cards */
.card {
  background: var(--background);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--primary);
  color: white;
}

.badge-secondary {
  background: var(--surface-2);
  color: var(--text-primary);
}

.badge-accent {
  background: var(--accent);
  color: white;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--surface-2);
  z-index: 1000;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--surface);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
}

.search-btn:hover {
  border-color: var(--primary);
  color: var(--text-primary);
}

.mobile-menu-btn {
  display: none;
  padding: var(--space-2);
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  overflow: hidden;
}

.hero-carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}

.hero-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  padding: var(--space-8);
  background: linear-gradient(135deg, var(--secondary) 0%, #2D2D2D 100%);
  border-radius: var(--radius-xl);
  margin: 0 var(--space-4);
}

.hero-content {
  color: white;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--primary);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: white;
  margin-bottom: var(--space-4);
}

.hero-description {
  color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-6);
  font-size: 1.125rem;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.hero-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.hero-price .original {
  text-decoration: line-through;
  color: rgba(255,255,255,0.5);
  font-size: 1.25rem;
}

.hero-price .sale {
  color: var(--accent);
  font-size: 2rem;
  font-weight: 700;
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.hero-image img {
  width: 100%;
  height: 300px;
  object-fit: cover;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-6);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-full);
  background: var(--surface-2);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--primary);
  width: 32px;
}

/* Course Cards */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--background);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.course-thumbnail {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.course-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-thumbnail img {
  transform: scale(1.05);
}

.course-badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--primary);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

.course-content {
  padding: var(--space-4);
}

.course-category {
  font-size: 0.75rem;
  color: var(--primary);
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: var(--space-2);
}

.course-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
  line-height: 1.4;
}

.course-instructor {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.course-stats {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-3);
}

.course-rating {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--warning);
  font-weight: 600;
}

.course-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.course-price .original {
  text-decoration: line-through;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.course-price .sale {
  color: var(--primary);
  font-size: 1.25rem;
  font-weight: 700;
}

/* Section Styling */
.section {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-8);
}

.section-title {
  font-size: 2rem;
  font-weight: 700;
}

/* Value Props */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.value-prop-card {
  padding: var(--space-6);
  background: var(--surface);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  background: var(--surface-2);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  color: white;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-4);
}

.value-prop-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.value-prop-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Footer */
.footer {
  background: var(--secondary);
  color: white;
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-section h4 {
  color: white;
  font-size: 1rem;
  margin-bottom: var(--space-4);
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--space-2);
}

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: white;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
}

.footer-legal a:hover {
  color: white;
}

.footer-socials {
  display: flex;
  gap: var(--space-4);
}

.footer-socials a {
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer-socials a:hover {
  color: white;
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  cursor: pointer;
}

.footer-accordion-header h4 {
  margin: 0;
}

.footer-accordion-content {
  display: none;
  padding-bottom: var(--space-4);
}

.footer-accordion-content.open {
  display: block;
}

/* Carousel Container */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-6);
  transition: transform 0.4s ease;
}

.carousel-card {
  flex: 0 0 calc(33.333% - var(--space-6));
  min-width: 280px;
}

/* Promo Banner */
.promo-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(135deg, var(--primary) 0%, #D12600 100%);
  color: white;
  padding: var(--space-4) var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-6);
  z-index: 999;
  transform: translateY(0);
  transition: transform var(--transition-base);
}

.promo-banner.hidden {
  transform: translateY(100%);
}

.promo-content {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.promo-text {
  font-weight: 600;
}

.promo-countdown {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: monospace;
  font-size: 1.25rem;
}

.promo-close {
  position: absolute;
  right: var(--space-4);
  background: rgba(255,255,255,0.2);
  border: none;
  color: white;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast);
}

.promo-close:hover {
  background: rgba(255,255,255,0.3);
}

/* Specialization Carousel */
.spec-carousel {
  position: relative;
  overflow: hidden;
}

.spec-slide {
  display: none;
}

.spec-slide.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

/* Pricing Toggle */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
}

.pricing-tab {
  padding: var(--space-3) var(--space-6);
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  position: relative;
  transition: color var(--transition-fast);
}

.pricing-tab.active {
  color: var(--text-primary);
}

.pricing-tab.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Pricing Card */
.pricing-card {
  background: var(--background);
  border: 2px solid var(--surface-2);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.pricing-card.featured {
  border-color: var(--primary);
  position: relative;
}

.pricing-card.featured::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-price {
  font-size: 3rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-2);
}

.pricing-period {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: var(--space-4);
}

.pricing-savings {
  display: inline-block;
  background: var(--accent);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--space-6);
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--surface-2);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) 0;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-base);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: var(--space-6);
  line-height: 1.7;
}

/* Sidebar Filters */
.sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-6));
  max-height: calc(100vh - var(--header-height) - var(--space-12));
  overflow-y: auto;
  padding-right: var(--space-4);
}

.sidebar-section {
  margin-bottom: var(--space-6);
}

.sidebar-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
  letter-spacing: 0.05em;
}

.sidebar-list {
  list-style: none;
}

.sidebar-list li {
  margin-bottom: var(--space-2);
}

.sidebar-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.sidebar-link:hover {
  background: var(--surface);
  color: var(--primary);
}

.sidebar-link.active {
  background: var(--primary);
  color: white;
}

.sidebar-link .count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.sidebar-link.active .count {
  color: rgba(255,255,255,0.7);
}

/* Projects Masonry */
.masonry-grid {
  columns: 4;
  column-gap: var(--space-6);
}

.masonry-item {
  break-inside: avoid;
  margin-bottom: var(--space-6);
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  cursor: pointer;
}

.masonry-item img {
  width: 100%;
  display: block;
  transition: transform var(--transition-slow);
}

.masonry-item:hover img {
  transform: scale(1.05);
}

.masonry-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-4);
  background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
  color: white;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.masonry-item:hover .masonry-overlay {
  opacity: 1;
}

.masonry-title {
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-author {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.masonry-stats {
  display: flex;
  gap: var(--space-4);
  margin-top: var(--space-2);
  font-size: 0.875rem;
}

/* Filter Bar */
.filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
  padding: var(--space-4);
  background: var(--surface);
  border-radius: var(--radius-lg);
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.filter-dropdown {
  position: relative;
}

.filter-select {
  appearance: none;
  padding: var(--space-2) var(--space-8) var(--space-2) var(--space-4);
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  cursor: pointer;
  min-width: 160px;
}

.filter-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.filter-chip {
  padding: var(--space-2) var(--space-4);
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-chip:hover,
.filter-chip.active {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

/* Login Form */
.login-container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-8);
  background: linear-gradient(135deg, var(--surface) 0%, var(--background) 100%);
}

.login-card {
  width: 100%;
  max-width: 420px;
  background: var(--background);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-xl);
}

.login-header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.login-header h1 {
  margin-bottom: var(--space-2);
}

.login-header p {
  color: var(--text-secondary);
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-weight: 500;
  background: var(--background);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.social-btn:hover {
  background: var(--surface);
  border-color: var(--text-muted);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin: var(--space-6) 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--surface-2);
}

.form-group {
  margin-bottom: var(--space-4);
}

.form-label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: var(--space-2);
}

.form-input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: border-color var(--transition-fast);
}

.form-input:focus {
  outline: none;
  border-color: var(--primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: var(--space-3);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  cursor: pointer;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: 0.875rem;
  color: var(--primary);
  margin-bottom: var(--space-6);
}

.login-btn {
  width: 100%;
  padding: var(--space-4);
  background: var(--primary);
  color: white;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.login-btn:hover {
  background: var(--primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: var(--space-6);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.login-footer a {
  color: var(--primary);
  font-weight: 600;
}

/* Plus Page Carousels */
.plus-carousel {
  position: relative;
}

.plus-carousel .carousel-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
}

.plus-carousel .carousel-track::-webkit-scrollbar {
  display: none;
}

.plus-carousel .carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}

.plus-carousel .carousel-btn.prev {
  left: var(--space-4);
}

.plus-carousel .carousel-btn.next {
  right: var(--space-4);
}

/* Credits Features */
.credits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-6);
}

.credit-card {
  background: var(--surface);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  text-align: center;
}

.credit-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  background: var(--primary);
  color: white;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.credit-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.credit-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-slide {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-image {
    order: -1;
  }

  .masonry-grid {
    columns: 3;
  }

  .carousel-card {
    flex: 0 0 calc(50% - var(--space-6));
  }
}

@media (max-width: 768px) {
  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .nav { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero-slide {
    padding: var(--space-6);
  }

  .hero-title { font-size: 1.75rem; }

  .masonry-grid {
    columns: 2;
  }

  .carousel-card {
    flex: 0 0 calc(100% - var(--space-6));
  }

  .section {
    padding: var(--space-10) 0;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-accordion {
    display: block;
  }

  .footer-links-desktop {
    display: none;
  }

  .filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-group {
    flex-wrap: wrap;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: var(--space-2);
  }

  .spec-slide.active {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    columns: 1;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .hero-carousel-inner,
  .carousel-track {
    transition: none;
  }
}

/* CreativeHub Design System */
:root {
  /* Colors - bold, modern, professional */
  --primary: #F02D00;
  --primary-dark: #D12600;
  --secondary: #171717;
  --background: #FFFFFF;
  --surface: #F8FAFC;
  --surface-2: #F1F5F9;
  --text-primary: #171717;
  --text-secondary: #64748B;
  --text-muted: #94A3B8;
  --accent: #00C9A7;
  --accent-hover: #00B094;
  --success: #10B981;
  --warning: #F59E0B;
  --error: #EF4444;

  /* Typography */
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset & Base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--background);
  min-height: 100vh;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, textarea, select { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-primary);
}

h1 { font-size: 3rem; font-weight: 700; }
h2 { font-size: 2.25rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

p { color: var(--text-secondary); }

/* Utility Classes */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--secondary);
  color: white;
}

.btn-outline {
  border: 2px solid var(--secondary);
  background: transparent;
}

.btn-outline:hover {
  background: var(--secondary);
  color: white;
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
}

.btn-ghost:hover {
  background: var(--surface-2);
}

/* Cards */
.card {
  background: var(--background);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--primary);
  color: white;
}

.badge-secondary {
  background: var(--surface-2);
  color: var(--text-primary);
}

.badge-accent {
  background: var(--accent);
  color: white;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--surface-2);
  z-index: 1000;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--surface);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
}

.search-btn:hover {
  border-color: var(--primary);
  color: var(--text-primary);
}

.mobile-menu-btn {
  display: none;
  padding: var(--space-2);
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  overflow: hidden;
}

.hero-carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}

.hero-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  padding: var(--space-8);
  background: linear-gradient(135deg, var(--secondary) 0%, #2D2D2D 100%);
  border-radius: var(--radius-xl);
  margin: 0 var(--space-4);
}

.hero-content {
  color: white;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--primary);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: white;
  margin-bottom: var(--space-4);
}

.hero-description {
  color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-6);
  font-size: 1.125rem;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.hero-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.hero-price .original {
  text-decoration: line-through;
  color: rgba(255,255,255,0.5);
  font-size: 1.25rem;
}

.hero-price .sale {
  color: var(--accent);
  font-size: 2rem;
  font-weight: 700;
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.hero-image img {
  width: 100%;
  height: 300px;
  object-fit: cover;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-6);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-full);
  background: var(--surface-2);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--primary);
  width: 32px;
}

/* Course Cards */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--background);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.course-thumbnail {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.course-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-thumbnail img {
  transform: scale(1.05);
}

.course-badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--primary);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

.course-content {
  padding: var(--space-4);
}

.course-category {
  font-size: 0.75rem;
  color: var(--primary);
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: var(--space-2);
}

.course-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
  line-height: 1.4;
}

.course-instructor {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
}

.course-stats {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-3);
}

.course-rating {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--warning);
  font-weight: 600;
}

.course-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.course-price .original {
  text-decoration: line-through;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.course-price .sale {
  color: var(--primary);
  font-size: 1.25rem;
  font-weight: 700;
}

/* Section Styling */
.section {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-8);
}

.section-title {
  font-size: 2rem;
  font-weight: 700;
}

/* Value Props */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--space-6);
}

.value-prop-card {
  padding: var(--space-6);
  background: var(--surface);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

.value-prop-card:hover {
  background: var(--surface-2);
  transform: translateY(-2px);
}

.value-prop-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  color: white;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-4);
}

.value-prop-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.value-prop-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Footer */
.footer {
  background: var(--secondary);
  color: white;
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-section h4 {
  color: white;
  font-size: 1rem;
  margin-bottom: var(--space-4);
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--space-2);
}

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: white;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  color: rgba(255,255,255,0.7);
  font-size: 0.875rem;
}

.footer-legal a:hover {
  color: white;
}

.footer-socials {
  display: flex;
  gap: var(--space-4);
}

.footer-socials a {
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer-socials a:hover {
  color: white;
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  cursor: pointer;
}

.footer-accordion-header h4 {
  margin: 0;
}

.footer-accordion-content {
  display: none;
  padding-bottom: var(--space-4);
}

.footer-accordion-content.open {
  display: block;
}

/* Carousel Container */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-6);
  transition: transform 0.4s ease;
}

.carousel-card {
  flex: 0 0 calc(33.333% - var(--space-6));
  min-width: 280px;
}

/* Promo Banner */
.promo-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(135deg, var(--primary) 0%, #D12600 100%);
  color: white;
  padding: var(--space-4) var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-6);
  z-index: 999;
  transform: translateY(0);
  transition: transform var(--transition-base);
}

.promo-banner.hidden {
  transform: translateY(100%);
}

.promo-content {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.promo-text {
  font-weight: 600;
}

.promo-countdown {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: monospace;
  font-size: 1.25rem;
}

.promo-close {
  position: absolute;
  right: var(--space-4);
  background: rgba(255,255,255,0.2);
  border: none;
  color: white;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast);
}

.promo-close:hover {
  background: rgba(255,255,255,0.3);
}

/* Specialization Carousel */
.spec-carousel {
  position: relative;
  overflow: hidden;
}

.spec-slide {
  display: none;
}

.spec-slide.active {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

/* Pricing Toggle */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
}

.pricing-tab {
  padding: var(--space-3) var(--space-6);
  font-weight: 600;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  position: relative;
  transition: color var(--transition-fast);
}

.pricing-tab.active {
  color: var(--text-primary);
}

.pricing-tab.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

/* Pricing Card */
.pricing-card {
  background: var(--background);
  border: 2px solid var(--surface-2);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.pricing-card.featured {
  border-color: var(--primary);
  position: relative;
}

.pricing-card.featured::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-price {
  font-size: 3rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-2);
}

.pricing-period {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: var(--space-4);
}

.pricing-savings {
  display: inline-block;
  background: var(--accent);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--space-6);
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--surface-2);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) 0;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-base);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: var(--space-6);
  line-height: 1.7;
}

/* Sidebar Filters */
.sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-6));
  max-height: calc(100vh - var(--header-height) - var(--space-12));
  overflow-y: auto;
  padding-right: var(--space-4);
}

.sidebar-section {
  margin-bottom: var(--space-6);
}

.sidebar-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: var(--space-3);
  letter-spacing: 0.05em;
}

.sidebar-list {
  list-style: none;
}

.sidebar-list li {
  margin-bottom: var(--space-2);
}

.sidebar-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.sidebar-link:hover {
  background: var(--surface);
  color: var(--primary);
}

.sidebar-link.active {
  background: var(--primary);
  color: white;
}

.sidebar-link .count {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.sidebar-link.active .count {
  color: rgba(255,255,255,0.7);
}

/* Projects Masonry */
.masonry-grid {
  columns: 4;
  column-gap: var(--space-6);
}

.masonry-item {
  break-inside: avoid;
  margin-bottom: var(--space-6);
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  cursor: pointer;
}

.masonry-item img {
  width: 100%;
  display: block;
  transition: transform var(--transition-slow);
}

.masonry-item:hover img {
  transform: scale(1.05);
}

.masonry-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-4);
  background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
  color: white;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.masonry-item:hover .masonry-overlay {
  opacity: 1;
}

.masonry-title {
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-author {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.masonry-stats {
  display: flex;
  gap: var(--space-4);
  margin-top: var(--space-2);
  font-size: 0.875rem;
}

/* Filter Bar */
.filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
  padding: var(--space-4);
  background: var(--surface);
  border-radius: var(--radius-lg);
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.filter-dropdown {
  position: relative;
}

.filter-select {
  appearance: none;
  padding: var(--space-2) var(--space-8) var(--space-2) var(--space-4);
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  cursor: pointer;
  min-width: 160px;
}

.filter-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.filter-chip {
  padding: var(--space-2) var(--space-4);
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-chip:hover,
.filter-chip.active {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

/* Login Form */
.login-container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-8);
  background: linear-gradient(135deg, var(--surface) 0%, var(--background) 100%);
}

.login-card {
  width: 100%;
  max-width: 420px;
  background: var(--background);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-xl);
}

.login-header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.login-header h1 {
  margin-bottom: var(--space-2);
}

.login-header p {
  color: var(--text-secondary);
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-weight: 500;
  background: var(--background);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.social-btn:hover {
  background: var(--surface);
  border-color: var(--text-muted);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin: var(--space-6) 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--surface-2);
}

.form-group {
  margin-bottom: var(--space-4);
}

.form-label {
  display: block;
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: var(--space-2);
}

.form-input {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: border-color var(--transition-fast);
}

.form-input:focus {
  outline: none;
  border-color: var(--primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: var(--space-3);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  cursor: pointer;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: 0.875rem;
  color: var(--primary);
  margin-bottom: var(--space-6);
}

.login-btn {
  width: 100%;
  padding: var(--space-4);
  background: var(--primary);
  color: white;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.login-btn:hover {
  background: var(--primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: var(--space-6);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.login-footer a {
  color: var(--primary);
  font-weight: 600;
}

/* Plus Page Carousels */
.plus-carousel {
  position: relative;
}

.plus-carousel .carousel-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
}

.plus-carousel .carousel-track::-webkit-scrollbar {
  display: none;
}

.plus-carousel .carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}

.plus-carousel .carousel-btn.prev {
  left: var(--space-4);
}

.plus-carousel .carousel-btn.next {
  right: var(--space-4);
}

/* Credits Features */
.credits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-6);
}

.credit-card {
  background: var(--surface);
  padding: var(--space-6);
  border-radius: var(--radius-lg);
  text-align: center;
}

.credit-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  background: var(--primary);
  color: white;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.credit-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.credit-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-slide {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-image {
    order: -1;
  }

  .masonry-grid {
    columns: 3;
  }

  .carousel-card {
    flex: 0 0 calc(50% - var(--space-6));
  }
}

@media (max-width: 768px) {
  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .nav { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero-slide {
    padding: var(--space-6);
  }

  .hero-title { font-size: 1.75rem; }

  .masonry-grid {
    columns: 2;
  }

  .carousel-card {
    flex: 0 0 calc(100% - var(--space-6));
  }

  .section {
    padding: var(--space-10) 0;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-accordion {
    display: block;
  }

  .footer-links-desktop {
    display: none;
  }

  .filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-group {
    flex-wrap: wrap;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: var(--space-2);
  }

  .spec-slide.active {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    columns: 1;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .hero-carousel-inner,
  .carousel-track {
    transition: none;
  }
}

raw_arguments.content:
/* CreativeHub Design System */
:root {
  /* Colors - bold, modern, professional */
  --primary: #F02D00;
  --primary-dark: #D12600;
  --secondary: #171717;
  --background: #FFFFFF;
  --surface: #F8FAFC;
  --surface-2: #F1F5F9;
  --text-primary: #171717;
  --text-secondary: #64748B;
  --text-muted: #94A3B8;
  --accent: #00C9A7;
  --accent-hover: #00B094;
  --success: #10B981;
  --warning: #F59E0B;
  --error: #EF4444;

  /* Typography */
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset & Base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--background);
  min-height: 100vh;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, textarea, select { font-family: inherit; font-size: inherit; }

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-primary);
}

h1 { font-size: 3rem; font-weight: 700; }
h2 { font-size: 2.25rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

p { color: var(--text-secondary); }

/* Utility Classes */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--primary);
  color: white;
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--secondary);
  color: white;
}

.btn-outline {
  border: 2px solid var(--secondary);
  background: transparent;
}

.btn-outline:hover {
  background: var(--secondary);
  color: white;
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
}

.btn-ghost:hover {
  background: var(--surface-2);
}

/* Cards */
.card {
  background: var(--background);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--primary);
  color: white;
}

.badge-secondary {
  background: var(--surface-2);
  color: var(--text-primary);
}

.badge-accent {
  background: var(--accent);
  color: white;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--surface-2);
  z-index: 1000;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: var(--radius-full);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--surface);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: all var(--transition-fast);
}

.search-btn:hover {
  border-color: var(--primary);
  color: var(--text-primary);
}

.mobile-menu-btn {
  display: none;
  padding: var(--space-2);
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  padding: calc(var(--header-height) + var(--space-8)) 0 var(--space-8);
  overflow: hidden;
}

.hero-carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}

.hero-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
  padding: var(--space-8);
  background: linear-gradient(135deg, var(--secondary) 0%, #2D2D2D 100%);
  border-radius: var(--radius-xl);
  margin: 0 var(--space-4);
}

.hero-content {
  color: white;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--primary);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: white;
  margin-bottom: var(--space-4);
}

.hero-description {
  color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-6);
  font-size: 1.125rem;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: var(--space-6);
  margin-bottom: var(--space-6);
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.hero-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.hero-price .original {
  text-decoration: line-through;
  color: rgba(255,255,255,0.5);
  font-size: 1.25rem;
}

.hero-price .sale {
  color: var(--accent);
  font-size: 2rem;
  font-weight: 700;
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.hero-image img {
  width: 100%;
  height: 300px;
  object-fit: cover;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  margin-top: var(--space-6);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border: 1px solid var(--surface-2);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-full);
  background: var(--surface-2);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--primary);
  width: 32px;
}

/* Course Cards */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--background);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.course-thumbnail {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.course-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-thumbnail img {
  transform: scale(1.05);
}

.course-badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  background: var(--primary);
  color: white;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

.course-content {
  padding: var(--space-4);
}

.course-category {
  font-size: 0.75rem;
  color: var(--primary);
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: var(--space-2);
}

.course-title {
