}

.promo-content {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.promo-text {
  font-weight: 600;
}

.promo-countdown {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: monospace;
