}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--surface-2);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-6) 0;
  font-size: 1.125rem;
