}

/* Projects Masonry */
.masonry-grid {
  columns: 4;
  column-gap: var(--space-6);
}

.masonry-item {
  break-inside: avoid;
  margin-bottom: var(--space-6);
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  cursor: pointer;
}

.masonry-item img {
  width: 100%;
