  transition: transform var(--transition-slow);
}

.masonry-item:hover img {
  transform: scale(1.05);
}

.masonry-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-4);
  background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
  color: white;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.masonry-item:hover .masonry-overlay {
  opacity: 1;
}

.masonry-title {
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-author {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}

.masonry-stats {
  display: flex;
  gap: var(--space-4);
  margin-top: var(--space-2);
  font-size: 0.875rem;
}

/* Filter Bar */
.filter-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
  padding: var(--space-4);
  background: var(--surface);
  border-radius: var(--radius-lg);
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.filter-dropdown {
  position: relative;
}

.filter-select {
