  scroll-behavior: smooth;
  scrollbar-width: none;
}

.plus-carousel .carousel-track::-webkit-scrollbar {
  display: none;
}

.plus-carousel .carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}

.plus-carousel .carousel-btn.prev {
  left: var(--space-4);
}

.plus-carousel .carousel-btn.next {
  right: var(--space-4);
}

/* Credits Features */
.credits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-6);
}

.credit-card {
  background: var(--surface);
  padding: var(--space-6);
