  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.credit-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.credit-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-slide {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-image {
    order: -1;
  }

  .masonry-grid {
    columns: 3;
  }

  .carousel-card {
    flex: 0 0 calc(50% - var(--space-6));
  }
}

@media (max-width: 768px) {
  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .nav { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero-slide {
    padding: var(--space-6);
  }

  .hero-title { font-size: 1.75rem; }

  .masonry-grid {
    columns: 2;
  }

  .carousel-card {
    flex: 0 0 calc(100% - var(--space-6));
  }

  .section {
    padding: var(--space-10) 0;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-accordion {
    display: block;
  }

  .footer-links-desktop {
    display: none;
  }

  .filter-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-group {
    flex-wrap: wrap;
  }

  .pricing-toggle {
    flex-direction: column;
    gap: var(--space-2);
  }

  .spec-slide.active {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    columns: 1;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .hero-carousel-inner,
  .carousel-track {
    transition: none;
  }
}

